llm_calls.content:
{
  "task_summary": "Predict whether an adult will move to a different residence within the next year using ACS person-level attributes.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 19,
      "rationale": "Directly reflects current commuting burden, which is strongly tied to residential mobility and tends to generalize across states."
    },
    {
      "rank": 2,
      "feature_id": 18,
      "rationale": "Work hours proxy labor-market attachment and life stability, both relevant to moving decisions in a broadly portable way."
    },
    {
      "rank": 3,
      "feature_id": 0,
      "rationale": "Age is a stable predictor of mobility stage across states, with clear life-cycle effects."
    },
    {
      "rank": 4,
      "feature_id": 1,
      "rationale": "Education captures socioeconomic status and mobility propensity without being overly state-specific."
    },
    {
      "rank": 5,
      "feature_id": 17,
      "rationale": "Employment status is closely related to relocation likelihood and household stability."
    },
    {
      "rank": 6,
      "feature_id": 20,
      "rationale": "Income is a strong general predictor of moving behavior, though it can be noisy and distribution-shifted."
    },
    {
      "rank": 7,
      "feature_id": 2,
      "rationale": "Marital status helps capture household formation and stability, which affect mobility across regions."
    },
    {
      "rank": 8,
      "feature_id": 10,
      "rationale": "Household relationship is informative about family structure and whether a person is likely to move."
    },
    {
      "rank": 9,
      "feature_id": 3,
      "rationale": "Sex can carry modest demographic signal for mobility patterns, but should be used cautiously."
    },
    {
      "rank": 10,
      "feature_id": 4,
      "rationale": "Disability status affects housing and moving constraints in a fairly transferable way."
    },
    {
      "rank": 11,
      "feature_id": 11,
      "rationale": "Hearing difficulty is a general health-related constraint that may influence mobility decisions."
    },
    {
      "rank": 12,
      "feature_id": 12,
      "rationale": "Vision difficulty is similarly relevant as a broad functional limitation, though weaker than core socioeconomic features."
    },
    {
      "rank": 13,
      "feature_id": 13,
      "rationale": "Cognitive difficulty can affect independence and relocation behavior, but is noisier and less directly tied to moving."
    },
    {
      "rank": 14,
      "feature_id": 9,
      "rationale": "Nativity captures broad migration background, but can also act as a demographic shortcut and vary in composition by state."
    },
    {
      "rank": 15,
      "feature_id": 6,
      "rationale": "Citizenship status is somewhat predictive of mobility, but may encode immigration composition differences across states."
    },
    {
      "rank": 16,
      "feature_id": 14,
      "rationale": "Race can correlate with mobility through structural factors, but it is also a strong proxy for geography and state-specific demographics."
    },
    {
      "rank": 17,
      "feature_id": 8,
      "rationale": "Ancestry is often a brittle demographic proxy with limited direct causal relation to moving."
    },
    {
      "rank": 18,
      "feature_id": 16,
      "rationale": "Class of worker reflects job type and stability, but can be highly state- and industry-composition-dependent."
    },
    {
      "rank": 19,
      "feature_id": 7,
      "rationale": "Military service is only weakly related to residential mobility for the general population and can be sparse."
    },
    {
      "rank": 20,
      "feature_id": 15,
      "rationale": "Grandparent-care status is niche and likely noisy for this target, with limited generalizable signal."
    },
    {
      "rank": 21,
      "feature_id": 5,
      "rationale": "Employment status of parents is mainly defined for children and is least relevant for adult mobility prediction."
    }
  ]
}
